// Differential checks of RecordUpdate-pbo.js against Lean, generated by leanscript --check
import * as M from "./RecordUpdate-pbo.js";

function show(v) {
  if (Array.isArray(v) || ArrayBuffer.isView(v)) return "#[" + [...v].map(show).join(", ") + "]";
  // a list of cons cells (`ListRepr.taggedUnion`) is shown as its elements
  if (v !== null && typeof v === "object" && (v.tag === 0 || v.tag === 1)) {
    const a = [];
    for (; v.tag === 1; v = v._2) a.push(v._1);
    return show(a);
  }
  // a record (a structure-like type) is shown as its fields: `{a, b}`
  if (v !== null && typeof v === "object" && !("tag" in v) && "_1" in v) {
    const fs = [];
    for (let i = 1; ("_" + i) in v; i++) fs.push(show(v["_" + i]));
    return "{" + fs.join(", ") + "}";
  }
  return String(v);
}
function floatBits(x) {
  return String(new BigUint64Array(new Float64Array([x]).buffer)[0]);
}
function isNaNBits(s) {
  const b = BigInt(s);
  return ((b >> 52n) & 0x7ffn) === 0x7ffn && (b & 0xfffffffffffffn) !== 0n;
}
let passed = 0, failed = 0;
function check(label, thunk, expected, isFloat) {
  let got;
  try {
    const v = thunk();
    got = isFloat ? floatBits(v) : show(v);
    // NaN payloads differ between platforms: any NaN matches any NaN
    if (isFloat && Number.isNaN(v) && isNaNBits(expected)) got = expected;
  } catch (e) {
    got = "threw: " + e.message;
  }
  if (got === expected) passed++;
  else {
    failed++;
    console.log(`FAIL ${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(got)}`);
  }
}

check("test7((x) => x + 1, -7)", () => M.test7((x) => x + 1, -7), "{-5, -8, -6}", false);
check("test7((x) => x + 1, -1)", () => M.test7((x) => x + 1, -1), "{1, -2, 0}", false);
check("test7((x) => 2 - x, -7)", () => M.test7((x) => 2 - x, -7), "{10, 7, 9}", false);
check("test7((x) => x + 1, 0)", () => M.test7((x) => x + 1, 0), "{2, -1, 1}", false);
check("test7((x) => 2 - x, -1)", () => M.test7((x) => 2 - x, -1), "{4, 1, 3}", false);
check("test7((x) => x + 1, 1)", () => M.test7((x) => x + 1, 1), "{3, 0, 2}", false);
check("test7((x) => 2 - x, 0)", () => M.test7((x) => 2 - x, 0), "{3, 0, 2}", false);
check("test7((x) => x + 1, 2)", () => M.test7((x) => x + 1, 2), "{4, 1, 3}", false);
check("test7((x) => 2 - x, 1)", () => M.test7((x) => 2 - x, 1), "{2, -1, 1}", false);
check("test7((x) => x + 1, 3)", () => M.test7((x) => x + 1, 3), "{5, 2, 4}", false);
check("test7((x) => 2 - x, 2)", () => M.test7((x) => 2 - x, 2), "{1, -2, 0}", false);
check("test7((x) => x + 1, 12)", () => M.test7((x) => x + 1, 12), "{14, 11, 13}", false);
check("test7((x) => 2 - x, 3)", () => M.test7((x) => 2 - x, 3), "{0, -3, -1}", false);
check("test7((x) => 2 - x, 12)", () => M.test7((x) => 2 - x, 12), "{-9, -12, -10}", false);

console.log(`RecordUpdate-pbo.js: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
